import { useState, useEffect } from "react";

export default function SelectBox({
    label,
    options = [],
    value,
    onChange,
    isreq = false,
    placeholder = '',
    maxLength = 0,
    widthRem = '',          // e.g., "16rem"
    widthPercent = '100%', // e.g., "90%"
    disabled = false,
    sidebarOpen = true      // needs to be passed from parent
}) {
    const [selectWidth, setSelectWidth] = useState(widthRem || widthPercent);

    const calculateWidth = () => {
        const screenWidth = window.innerWidth;

         if (screenWidth < 769 || !sidebarOpen) {
            setSelectWidth(widthPercent); // use percent width if sidebar is closed or small screen
        } else {
            setSelectWidth(widthRem); // default/fallback fixed width for large screen + open sidebar
        }
    };

    useEffect(() => {
        calculateWidth();
        window.addEventListener('resize', calculateWidth);
        return () => window.removeEventListener('resize', calculateWidth);
    }, [widthRem, widthPercent, sidebarOpen]);

    return (
        <div style={{ width: selectWidth }}>
            <label style={{ fontSize: "0.9rem", marginTop:"0.13rem" }}>
                <strong>{label}</strong>
                {isreq && (
                    <span
                        className="text-danger"
                        style={{
                            fontSize: '1rem',
                            fontWeight: '600',
                            marginLeft: '0.2rem',
                        }}
                    >
                        *
                    </span>
                )}
            </label>

            <select
                value={value}
                onChange={onChange}
                className="form-control"
                style={{
                  
                    fontSize: "0.88rem",
                  
                }}
                disabled={disabled}
            >
                <option value="" disabled>
                    {placeholder || `Select ${label.toLowerCase()}`}
                </option>
                {options.map((opt) => {
                    const displayLabel = maxLength > 0 ? opt.label.slice(0, maxLength) : opt.label;
                    return (
                        <option key={opt.value} value={opt.value}>
                            {displayLabel}
                        </option>
                    );
                })}
            </select>
        </div>
    );
}
