import { useState, useEffect } from "react";

export default function InputBox({
    label,
    type = "text",
    placeholder = "",
    maxLength = 20,
    isreq = false,
    disable = false,
    text = "",
    widthPercent = "100%",
    value = "",
    onChange = () => { },
    sidebarOpen = true // ✅ Accept this from parent
}) {
    const [inputWidth, setInputWidth] = useState("");

    const calculateWidth = () => {
        const screenWidth = window.innerWidth;

        if (sidebarOpen && screenWidth >= 769) {
            // Sidebar is open and large screen → use ch-based width
            setInputWidth(`${maxLength + 5}ch`);
        } else {
            // Sidebar closed or small screen → use % width
            setInputWidth(widthPercent);
        }
    };

    useEffect(() => {
        calculateWidth();
        window.addEventListener("resize", calculateWidth);
        return () => window.removeEventListener("resize", calculateWidth);
    }, [maxLength, widthPercent, sidebarOpen]);


    return (
        <div className="form-group" style={{ width: inputWidth, minWidth: "150px" }}>
            <label style={{ fontWeight: "600", fontSize: "0.9rem" }}>
                <strong>{label}</strong>
            </label>
            {isreq ? (
                <span className="text-danger" style={{ fontSize: "1rem", fontWeight: "600", marginLeft: "0.2rem" }}>*</span>
            ) : (
                <span style={{ fontSize: "1.14rem", fontWeight: "600", marginLeft: "0.2rem" }}></span>
            )}
            <br />
            <input
                type={type}
                className="form-control"
                placeholder={placeholder}
                maxLength={maxLength}
                value={value}
                onChange={onChange}
                style={{
                    width: "100%",
                    fontSize: "0.88rem",
                    
                    borderColor: "#d2d2d3",
                    boxSizing: "border-box"
                }}
                disabled={disable}
            />
            <p style={{ fontSize: "0.82rem", marginTop: "0.3rem" }}>{text}</p>
        </div>
    );
}
