import { RotateSpinner } from "react-spinners-kit";

export default function Modal({ show, onClose, data, onChange, onSave, title, fields, loading }) {

    return (
        <div className="modal fade" id="exampleModal" tabIndex="-1" role="dialog" aria-labelledby="exampleModalLabel" >
            <div className="modal-dialog modal-dialog-centered modal-lg" role="document">
                <div className="modal-content" style={{ position: "relative" }}>

                    {/* Spinner Overlay */}
                    {loading && (
                        <div
                            style={{
                                position: "absolute",
                                top: 0,
                                left: 0,
                                right: 0,
                                bottom: 0,
                                backgroundColor: "rgba(255, 255, 255, 0.7)",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                zIndex: 100000
                            }}
                        >
                            <RotateSpinner color="black" />
                        </div>
                    )}

                    <div className="modal-header" style={{ backgroundColor: "#2392e0" }}>
                        <h5 className="modal-title" id="exampleModalLabel">{title}</h5>
                        <button type="button" onClick={onClose} className="close" data-dismiss="modal" aria-label="Close">
                            <span aria-hidden="true">&times;</span>
                        </button>
                    </div>

                    <div className="modal-body">
                       <form>
                            <div className="row">
                                {fields.map(({ key, label, isreq, inputtype = "input", options = [], placeholder = "" }) => {
                                    const colClass = inputtype === "textarea" ? "col-12" : "col-md-4";
                                    return (
                                        <div className={`form-group ${colClass}`} key={key} style={{ marginBottom: "1rem" }}>
                                            <label style={{ fontSize: "0.9rem", fontWeight: "600" }}>
                                                {label}
                                                {isreq && <span className="text-danger" style={{marginLeft:"0.2rem"}}>*</span>}
                                            </label>

                                            {inputtype === "input" && (
                                                <input
                                                    type="text"
                                                    className="form-control"
                                                    value={data[key] || ""}
                                                    onChange={(e) => onChange(key, e.target.value)}
                                                    required={isreq}
                                                    disabled={loading}
                                                    placeholder={placeholder}
                                                    style={{fontSize:"0.9rem"}}
                                                />
                                            )}

                                            {inputtype === "select" && (
                                                <select
                                                    value={data[key] || ""}
                                                    onChange={(e) => onChange(key, e.target.value)}
                                                    className="form-control"
                                                    required={isreq}
                                                    disabled={loading}
                                                    style={{fontSize:"0.9rem"}}
                                                >
                                                    <option value="" disabled>Select {label}</option>
                                                    {options.map((option, idx) => (
                                                        <option key={idx} value={option}>
                                                            {option}
                                                        </option>
                                                    ))}
                                                </select>
                                            )}

                                            {inputtype === "textarea" && (
                                                <textarea
                                                    className="form-control"
                                                    rows="2"
                                                    value={data[key] || ""}
                                                    onChange={(e) => onChange(key, e.target.value)}
                                                    required={isreq}
                                                    disabled={loading}
                                                    placeholder={placeholder}
                                                    style={{ resize: "vertical", fontSize:"0.9rem" }}

                                                />
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </form>
                    </div>

                    <div className="modal-footer">
                        <button type="button" className="btn btn-warning btn-glow" onClick={onClose} data-dismiss="modal" aria-label="Close" disabled={loading}>
                            Close
                        </button>
                        <button type="button" className="ml-1 btn btn-info btn-glow" onClick={onSave} disabled={loading}>
                            Save changes
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

