import '../Pages/CSS/Custom CSS/DLTMgt.css'

export default function DLTManagement() {
    return (
        <div className='dlt-container'>
            <div className='dlt-row' >
                <div class=" px-0 mr-1" style={{width:"30%"}}>
                    <div class="card bg-gradient-directional-info" style={{
                        backgroundImage: "linear-gradient(45deg, #228EB6, #4FC1E9",
                        backgroundRepeat: "repeat-x"
                    }}>
                        <div class="card-content">
                            <div class="card-body">
                                <div class="media d-flex">
                                    <div class="align-self-center">
                                        <i class="fa-solid fa-user-check text-white float-left" style={{ fontSize: "1.8rem" }}></i>

                                    </div>
                                    <div class="media-body text-white text-right">
                                        <h3 class="text-white">278</h3>
                                        <span>Sender ID</span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <div class=" px-0 mr-1" style={{width:"30%"}}>
                    <div class="card bg-gradient-directional-info" style={{
                        backgroundImage: "linear-gradient(to right, #298D74 0, #48CFAD 100%)",
                        backgroundRepeat: "repeat-x"
                    }}>
                        <div class="card-content">
                            <div class="card-body">
                                <div class="media d-flex">
                                    <div class="align-self-center">
                                        <i class="fa-solid fa-envelope-circle-check text-white float-left" style={{ fontSize: "1.8rem" }}></i>

                                    </div>
                                    <div class="media-body text-white text-right">
                                        <h3 class="text-white">278</h3>
                                        <span>Templates</span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <div class=" px-0" style={{width:"30%"}}>
                    <div class="card bg-gradient-directional-info" style={{
                        background: "#FFDD3C",
                        backgroundRepeat: "repeat-x"
                    }}>
                        <div class="card-content">
                            <div class="card-body">
                                <div class="media d-flex">
                                    <div class="align-self-center">
                                        <i class="fa-solid fa-building-circle-check text-white float-left" style={{ fontSize: "1.8rem" }}></i>
                                    </div>
                                    <div class="media-body text-white text-right">
                                        <h3 class="text-white">8</h3>
                                        <span>Entity ID</span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

          
        </div>
    );
}