                    entpEmailId: email,
                    entpMoblieNo: mobileno,
                    entpspocName: spocname,
                    entpspocEmail: spocemail,
                    entpspocMobile: primarycontact,
                    entpBillingCycle: billingcycle,
                    entpAddress: address,
