                    requestBody.deptEmailId = departmentemail;
                    requestBody.deptMoblieNo = departmentmobileno;
                    requestBody.deptSpocName = dspocname;
                    requestBody.deptSpocEmail = dspocemail;
                    requestBody.deptSpocMobile = dspocmobile;
