                        setaddress("");
                        setbillingcycle("");
                        setisdefaultdepartment("No");
                        setbillingtype("");
                        setdepartment("");
                        setprimarycontact("");
                        setdepartmentemail("");
                        setdspocname("");
                        setdepartmentmobileno("");
                        setdspocmobile("");
                        setdeptaddress("");
                        setdeptbillingcycle("");
                        setdeptbillingtype("");
